B.cwq=new A.bB("grape_merlot","Le Velours du Merlot","Merlot Velvet",null,"\ud83e\uded0",B.ei,B.bw,"D\xe9guster ou avoir en cave au moins 2 vins \xe0 dominante Merlot (Pomerol, Saint-\xc9milion...).","Taste plush and opulent Merlot wines.",null,"\xab C\xe9page embl\xe9matique de la rive droite bordelaise, le Merlot s\xe9duit par sa chair pulpeuse, sa texture velout\xe9e et ses ar\xf4mes gourmands de prune noire, m\xfbre et chocolat noir. \xbb",null,null,2,null)
B.cwS=new A.bB("grape_sauvignon_blanc","L'\xc9clat du Sauvignon Blanc","Sauvignon Vibrance",null,"\ud83c\udf4b",B.ei,B.bw,"D\xe9guster ou avoir en cave au moins 2 vins de Sauvignon Blanc (Sancerre, Pouilly-Fum\xe9...).",u.fY,null,"\xab R\xe9put\xe9 pour son acidit\xe9 vivifiante et sa fra\xeecheur aromatique ! Sur le silex, il offre une note min\xe9rale de pierre \xe0 fusil ; sur le calcaire, il exhale les agrumes et le buis. \xbb",null,null,2,null)
B.cwF=new A.bB("grape_grenache","Le G\xe9n\xe9reux Grenache","Generous Grenache",null,"\u2600\ufe0f",B.ei,B.bw,"D\xe9guster ou avoir en cave au moins 2 vins \xe0 dominante Grenache (Rh\xf4ne sud, Priorat...).",u.ob,null,"\xab Roi du pourtour m\xe9diterran\xe9en bravant le vent et la s\xe9cheresse, le Grenache offre une texture ronde et soyeuse, accompagn\xe9e de notes de fraise confite, poivre et garrigue. \xbb",null,null,2,null)
B.cw6=new A.bB("grape_cabernet_franc","La Finesse du Cabernet Franc","Cabernet Franc Finesse",null,"\ud83e\udea8",B.ei,B.bw,"D\xe9guster ou avoir en cave au moins 2 vins de Cabernet Franc (Chinon, Bourgueil, Saumur...).",u.aA,null,"\xab P\xe8re g\xe9n\xe9tique du Cabernet Sauvignon et du Merlot, le Cabernet Franc charme par son \xe9l\xe9gance lig\xe9rienne : parfums de framboise sauvage, touche de graphite et note florale de violette. \xbb",null,null,2,null)
B.cwh=new A.bB("grape_sangiovese","Le Sang de Jupiter","Blood of Jupiter",null,"\ud83e\udd81",B.ei,B.bw,"D\xe9guster ou avoir en cave au moins 2 vins issus du Sangiovese (Chianti, Brunello...).",u.bQ,null,'\xab Son nom latin "Sanguis Jovis" \xe9voque le roi des dieux romains. Robe rubis \xe9tincelante, acidit\xe9 tonique et ar\xf4mes de cerise griotte et th\xe9 noir : le partenaire gastronomique parfait. \xbb',null,null,2,null)
B.cvv=new A.bB("grape_malbec","La Nuit Noire du Malbec","Dark Night of Malbec",null,"\ud83d\udda4",B.ei,B.bw,"D\xe9guster ou avoir en cave au moins 2 vins \xe0 dominante Malbec / C\xf4t (Cahors, Mendoza...).",u.fA,null,"\xab Le \"vin noir\" du Moyen \xc2ge ! Le Malbec poss\xe8de une robe d'encre pourpre et tapisse la bouche d'ar\xf4mes denses de m\xfbre sauvage, cassis, r\xe9glisse noire et violette. \xbb",null,null,2,null)
